#!/bin/bash
# Fa provider for run-agent.sh
#
#   FA_PROVIDERS_QUEUE   (recommended, JSON array or @path) provider failover
#                        queue: [{"provider_type": ..., "provider_config":
#                        {"baseUrl": ..., "model": ..., "apiKeyEnv": ...}}]
