import json, os, sys
raw = os.environ.get("FA_PROVIDERS_QUEUE", "")
if raw.startswith("@"):
    with open(raw[1:], "r", encoding="utf-8") as f:
        raw = f.read()
arr = json.loads(raw)
if not isinstance(arr, list) or not arr:
